import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String[] line = scanner.nextLine().split(" ");
        int n = Integer.parseInt(line[0]);
        int h = Integer.parseInt(line[1]);

        int[][] nodeHeightArray = new int[36][36];
        nodeHeightArray[0][0] = 1;

        for (int totalNodes = 1; totalNodes < 36; totalNodes++) {
            for (int minHeight = 0; minHeight <= totalNodes; minHeight++) {
                for (int rootNode = 1; rootNode <= totalNodes; rootNode++) {
                    int leftSubtreeSize = rootNode - 1;
                    int rightSubtreeSize = totalNodes - rootNode;
                    int val1 = nodeHeightArray[leftSubtreeSize][0] * nodeHeightArray[rightSubtreeSize][0];
                    int minIndexLeft = Math.max(minHeight - 1, 0);
                    int minIndexRight = Math.max(minHeight - 1, 0);
                    int val2 = (nodeHeightArray[leftSubtreeSize][0] - nodeHeightArray[leftSubtreeSize][minIndexLeft]) *
                               (nodeHeightArray[rightSubtreeSize][0] - nodeHeightArray[rightSubtreeSize][minIndexRight]);
                    nodeHeightArray[totalNodes][minHeight] += val1 - val2;
                }
            }
        }

        System.out.println(nodeHeightArray[n][h]);
        scanner.close();
    }
}
